SELECT id, student_id, name, phone, role_id, password, role, college, avatar, status, create_time, login_time
FROM user



        AND name LIKE CONCAT('%', #{name}, '%')


        AND phone LIKE CONCAT('%', #{phone}, '%')


        AND role = #{role}


        AND college = #{college}


        AND status = #{status}


ORDER BY create_time DESC

SELECT id, student_id, name, phone, role_id, password, role, college, avatar, status, create_time, login_time
FROM user
WHERE id = #{id}

SELECT id, student_id, name, phone, role_id, password, role, college, avatar, status, create_time, login_time
FROM user
WHERE student_id = #{studentId}

mapper.update:
UPDATE user
SET login_time = NOW()
WHERE id = #{id}

UPDATE user
SET password = #{password}
WHERE id = #{id}
